using System;
using System.IO;
using System.Reflection;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.SceneManagement;

namespace PrototypeLab.Aquarium.Editor
{
    // R18: greedy fish gulp. Rebuilds only Fish0 from ArtSources/Cartoon/Export once:
    // the larger maw (Fish0.cartoon) and the faster Bite / SpitRecoil clips generated by
    // AquariumCartoonImport. The open scene is not touched (temporary additive scene),
    // and it waits for Edit mode. The cute monster alien is not rebuilt.
    // Menu: Aquarium > Characters > Apply fish0 greedy gulp (R18)
    [InitializeOnLoad]
    public static class Fish0FeastR18
    {
        const string Characters = "Assets/Demos/HideAndSeek/Characters/Resources/AquariumCharacters";
        const string Revision = "r18-gulp-1";
        public const float MouthRadius = .21f;
        static bool waiting;
        static string Export => Path.GetFullPath(Path.Combine(Application.dataPath, "../ArtSources/Cartoon/Export"));
        static string Marker => Path.Combine(Export, "Fish0.r18.applied");

        static Fish0FeastR18() { EditorApplication.delayCall += TryAuto; }

        static string Stamp()
        {
            string path = Path.Combine(Export, "Fish0.cartoon");
            if (!File.Exists(path)) return null;
            using (var md5 = System.Security.Cryptography.MD5.Create())
                return Revision + ":" + BitConverter.ToString(md5.ComputeHash(File.ReadAllBytes(path))).Replace("-", "").ToLowerInvariant();
        }

        static void TryAuto()
        {
            if (Application.isBatchMode) return;
            string stamp = Stamp();
            if (stamp == null) return;
            if (File.Exists(Marker) && File.ReadAllText(Marker).Trim() == stamp) return;
            if (EditorApplication.isPlayingOrWillChangePlaymode)
            {
                if (!waiting) { waiting = true; EditorApplication.playModeStateChanged += OnPlayMode; }
                return;
            }
            if (EditorApplication.isCompiling || EditorApplication.isUpdating) { EditorApplication.delayCall += TryAuto; return; }
            Apply();
        }

        static void OnPlayMode(PlayModeStateChange change)
        {
            if (change != PlayModeStateChange.EnteredEditMode) return;
            EditorApplication.playModeStateChanged -= OnPlayMode; waiting = false;
            EditorApplication.delayCall += TryAuto;
        }

        [MenuItem("Aquarium/Characters/Apply fish0 greedy gulp (R18)")]
        public static void Apply()
        {
            if (EditorApplication.isPlayingOrWillChangePlaymode) { Debug.LogWarning("Fish0 R18: exit Play mode first."); return; }
            var active = SceneManager.GetActiveScene();
            // An unsaved untitled scene cannot take an additive scene. Then the temporary
            // rig is built in place and removed again (script-made objects do not dirty it).
            bool additive = !string.IsNullOrEmpty(active.path);
            var temp = additive ? EditorSceneManager.NewScene(NewSceneSetup.EmptyScene, NewSceneMode.Additive) : active;
            var existing = new System.Collections.Generic.HashSet<GameObject>(active.GetRootGameObjects());
            if (additive) SceneManager.SetActiveScene(temp);
            try
            {
                var import = typeof(AquariumCartoonImport);
                var flags = BindingFlags.NonPublic | BindingFlags.Static;
                object data = import.GetMethod("Load", flags).Invoke(null, new object[] { "Fish0" });
                var rig = (Component)import.GetMethod("Rig", flags).Invoke(null, new object[] { data, Characters });
                UnityEngine.Object.DestroyImmediate(rig.gameObject);

                var fish = AssetDatabase.LoadAssetAtPath<GameObject>(Characters + "/Fish0.prefab");
                foreach (var species in Resources.LoadAll<AquariumSpecies>("AquariumCharacters"))
                {
                    species.normal = fish; species.feeding = fish; species.closedFeeding = fish;
                    species.feedingMouthRadius = MouthRadius;
                    EditorUtility.SetDirty(species);
                }

                var root = PrefabUtility.LoadPrefabContents(Characters + "/Fish0.prefab");
                try
                {
                    var morph = root.GetComponent<AquariumMorphMotion>();
                    if (morph == null) morph = root.AddComponent<AquariumMorphMotion>();
                    morph.leave = AssetDatabase.LoadAssetAtPath<AnimationClip>(Characters + "/AlienOctopus/FishOcto_MorphLeave.anim");
                    morph.arrive = AssetDatabase.LoadAssetAtPath<AnimationClip>(Characters + "/AlienOctopus/FishOcto_MorphArrive.anim");
                    PrefabUtility.SaveAsPrefabAsset(root, Characters + "/Fish0.prefab");
                }
                finally { PrefabUtility.UnloadPrefabContents(root); }

                AssetDatabase.SaveAssets();
                File.WriteAllText(Marker, Stamp());
                Debug.Log("FISH0_R18_APPLIED greedy gulp; meal radius " + MouthRadius);
            }
            catch (Exception e) { Debug.LogError("Fish0 R18 failed: " + (e.InnerException ?? e)); }
            finally
            {
                if (additive)
                {
                    if (active.IsValid()) SceneManager.SetActiveScene(active);
                    EditorSceneManager.CloseScene(temp, true);
                }
                else foreach (var go in active.GetRootGameObjects()) if (!existing.Contains(go)) UnityEngine.Object.DestroyImmediate(go);
            }
        }
    }
}
